Here is the commit message:
dmaengine: ti: Fix refcount leak in
 ti_dra7_xbar_route_allocate

of_parse_phandle() returns a node pointer with refcount
incremented, we should use of_node_put() on it when not needed anymore.

Add missing of_node_put() in to fix this.

Fixes: ec9bfa1e1a79 ("dmaengine: ti-dma-crossbar: dra7: Use bitops instead of idr")
Signed-off-by: Miaoqian Lin <linmq006@gmail.com>
Link: https://lore.kernel.org/r/20220605042723.17668-2-linmq006@gmail.com
Signed-off-by: Vinod Koul <vkoul@kernel.org>

Here is the root cause:
The bug is caused by the lack of a corresponding call to `of_node_put()` after using `of_parse_phandle()`, which increments the reference count of the node pointer. When the function encounters an error and returns early, the reference count is not decremented, leading to a memory leak as the node remains allocated but is no longer accessible.

Here is the patch:

 static void *ti_dra7_xbar_route_allocate(struct of_phandle_args *dma_spec,
 					 struct of_dma *ofdma)
 {
 	struct platform_device *pdev = of_find_device_by_node(ofdma->of_node);
 	struct ti_dra7_xbar_data *xbar = platform_get_drvdata(pdev);
 	struct ti_dra7_xbar_map *map;

 	if (dma_spec->args[0] >= xbar->xbar_requests) {
 		dev_err(&pdev->dev, "Invalid XBAR request number: %d\n",
 			dma_spec->args[0]);
 		return ERR_PTR(-EINVAL);
 	}

 	/* The of_node_put() will be done in the core for the node */
 	dma_spec->np = of_parse_phandle(ofdma->of_node, "dma-masters", 0);
 	if (!dma_spec->np) {
 		dev_err(&pdev->dev, "Can't get DMA master\n");
 		return ERR_PTR(-EINVAL);
 	}

 	map = kzalloc(sizeof(*map), GFP_KERNEL);
 	if (!map) {
 		of_node_put(dma_spec->np);
 		return ERR_PTR(-ENOMEM);
 	}

 	mutex_lock(&xbar->mutex);
 	map->xbar_out = find_first_zero_bit(xbar->dma_inuse,
 					    xbar->dma_requests);
 	if (map->xbar_out == xbar->dma_requests) {
 		mutex_unlock(&xbar->mutex);
 		dev_err(&pdev->dev, "Run out of free DMA requests\n");
 		kfree(map);
+		of_node_put(dma_spec->np);
 		return ERR_PTR(-ENOMEM);
 	}
 	set_bit(map->xbar_out, xbar->dma_inuse);
 	mutex_unlock(&xbar->mutex);

 	map->xbar_in = (u16)dma_spec->args[0];

 	dma_spec->args[0] = map->xbar_out + xbar->dma_offset;

 	dev_dbg(&pdev->dev, "Mapping XBAR%u to DMA%d\n",
 		map->xbar_in, map->xbar_out);

 	ti_dra7_xbar_write(xbar->iomem, map->xbar_out, map->xbar_in);

 	return map;
 }



